mapper.select:

where r.del_flag = '0'
 and r.resource_code like concat('%', #{query.resourceCode}, '%')
 and r.station_name like concat('%', #{query.stationName}, '%')
 and r.pile_no like concat('%', #{query.pileNo}, '%')
 and r.pile_type = #{query.pileType}
 and r.participate_status = #{query.participateStatus}
 and r.device_status = #{query.deviceStatus}
 and r.station_id in
    #{stationId}

 and r.station_id = #{query.stationId}
 and (r.pile_no like concat('%', #{query.keyword}, '%') or r.station_name like concat('%', #{query.keyword}, '%') or t.tenant_name like concat('%', #{query.keyword}, '%'))
order by r.resource_id


where r.del_flag = '0'
 and r.resource_code like concat('%', #{query.resourceCode}, '%')
 and r.station_name like concat('%', #{query.stationName}, '%')
 and r.pile_no like concat('%', #{query.pileNo}, '%')
 and r.pile_type = #{query.pileType}
 and r.participate_status = #{query.participateStatus}
 and r.device_status = #{query.deviceStatus}
 and r.station_id in
    #{stationId}

 and r.station_id = #{query.stationId}
 and (r.pile_no like concat('%', #{query.keyword}, '%') or r.station_name like concat('%', #{query.keyword}, '%') or t.tenant_name like concat('%', #{query.keyword}, '%'))
order by r.resource_id

select station_id as stationId, station_name as stationName, sum(adjustable_power) as adjustablePower, sum(valley_power) as valleyPower from dr_resource where del_flag = '0' and participate_flag = '1'
and station_id in #{id}
group by station_id, station_name order by
sum(valley_power) desc sum(adjustable_power) desc
limit #{limit}

select coalesce(t.tenant_name, '其他') as tenantName, coalesce(sub.event_count, 0) as eventCount from ( select r.tenant_id, count(distinct dd.event_id) as event_count from dr_resource r left join dr_dispatch dd on dd.pile_no = r.pile_no and dd.tenant_id = r.tenant_id and dd.del_flag = '0' where r.del_flag = '0' and r.participate_flag = '1'
and r.station_id in #{id}
group by r.tenant_id ) sub left join sys_tenant t on t.id = sub.tenant_id order by sub.event_count desc

select sub.station_name as stationName, coalesce(sub.event_count, 0) as eventCount from ( select r.station_id, r.station_name, count(distinct dd.event_id) as event_count from dr_resource r left join dr_dispatch dd on dd.pile_no = r.pile_no and dd.tenant_id = r.tenant_id and dd.del_flag = '0' where r.del_flag = '0' and r.participate_flag = '1'
and r.tenant_id = #{tenantId}
and r.station_id in #{id}
group by r.station_id, r.station_name ) sub order by sub.event_count desc
